  BRACKET: {
    caption: "From the independent topology-optimisation project. All figures simulated.",
    svg: "<svg width=\"100%\" viewBox=\"0 0 600 430\" role=\"img\" aria-labelledby=\"dwg-t dwg-d\">\n        <title id=\"dwg-t\">Technical drawing of a topology-optimised mounting bracket</title>\n        <desc id=\"dwg-d\">Front view of an L-shaped steel bracket with triangular lightening cut-outs, four mounting holes and callouts: mass down 29 percent, factor of safety 2.15 at 162 MPa peak stress, first natural frequency 142 hertz, R6 fillets. All figures simulated.</desc>\n        <rect class=\"ln-frame\" x=\"8\" y=\"8\" width=\"584\" height=\"414\"/>\n        <g class=\"ln-frame\"><path d=\"M158 8v8M308 8v8M458 8v8M158 422v-8M308 422v-8M458 422v-8M8 145h8M8 285h8M592 145h-8M592 285h-8\"/></g>\n        <!-- body -->\n        <path class=\"body-fill\" d=\"M70 92 H132 V142 L402 330 H442 V370 H70 Z\"/>\n        <path class=\"ln\" pathLength=\"1\" d=\"M70 92 H132 V142 L402 330 H442 V370 H70 Z\"/>\n        <!-- cut-outs with R6 corners -->\n        <path class=\"ln\" pathLength=\"1\" d=\"M156 196 L156 306 Q156 312 162 312 L246 312 Q254 312 249 306 L166 194 Q156 186 156 196 Z\"/>\n        <path class=\"ln\" pathLength=\"1\" d=\"M282 276 L282 306 Q282 312 288 312 L336 312 Q344 312 338 307 L292 271 Q282 266 282 276 Z\"/>\n        <!-- holes -->\n        <g class=\"d3\">\n          <circle class=\"ln\" pathLength=\"1\" cx=\"101\" cy=\"122\" r=\"9\"/>\n          <circle class=\"ln\" pathLength=\"1\" cx=\"101\" cy=\"230\" r=\"9\"/>\n          <circle class=\"ln\" pathLength=\"1\" cx=\"230\" cy=\"350\" r=\"9\"/>\n          <circle class=\"ln\" pathLength=\"1\" cx=\"400\" cy=\"350\" r=\"9\"/>\n        </g>\n        <!-- centre lines -->\n        <g class=\"ln-center\">\n          <path d=\"M84 122h34M101 105v34M84 230h34M101 213v34M213 350h34M230 333v34M383 350h34M400 333v34\"/>\n          <path d=\"M101 80v300\"/>\n        </g>\n        <!-- callouts -->\n        <g>\n          <path class=\"ln-thin\" d=\"M158 300 L118 404 H70\"/>\n          <text class=\"svg-t\" x=\"70\" y=\"399\">R6 typ.</text>\n\n          <path class=\"ln-red\" d=\"M236 248 L300 196 H462\"/>\n          <circle class=\"fill-red\" cx=\"236\" cy=\"248\" r=\"2.6\"/>\n          <text class=\"svg-t red\" x=\"306\" y=\"190\">Mass −29% (sim.)</text>\n\n          <path class=\"ln-red\" d=\"M360 318 L420 262 H570\"/>\n          <circle class=\"fill-red\" cx=\"360\" cy=\"318\" r=\"2.6\"/>\n          <text class=\"svg-t red\" x=\"426\" y=\"256\">FoS 2.15 at 162 MPa (sim.)</text>\n\n          <path class=\"ln-red\" d=\"M126 108 L190 66 H360\"/>\n          <circle class=\"fill-red\" cx=\"126\" cy=\"108\" r=\"2.6\"/>\n          <text class=\"svg-t red\" x=\"196\" y=\"60\">f₁ 142 Hz, +16% (sim.)</text>\n\n          <!-- mini title block -->\n          <rect class=\"ln-thin\" x=\"452\" y=\"378\" width=\"132\" height=\"36\"/>\n          <text class=\"svg-t sm\" x=\"458\" y=\"392\">Mounting bracket</text>\n          <text class=\"svg-t sm\" x=\"458\" y=\"407\">ANSYS to Fusion 360</text>\n        </g>\n      </svg>",
  },
